def find_marks(n, k, p, x, y, a):
    remaining_tests = n - k
    current_sum = sum(a)
    current_median = sorted(a)[(k + 1) // 2]

    def can_distribute(marks):
        nonlocal current_sum, current_median
        for mark in marks:
            current_sum += mark
            current_median = sorted(a + [mark])[(k + len(marks)) // 2]
            if current_sum > x or current_median < y:
                return False
        return True

    for i in range(remaining_tests, 0, -1):
        if current_sum + i * p <= x and current_median >= y:
            return [p] * i
        elif current_sum + i * 1 <= x and current_median >= y:
            return [1] * i
        else:
            for j in range(i - 1, 0, -1):
                if current_sum + j * p <= x and current_median >= y:
                    return [p] * j + [1] * (i - j)

    return [-1]

