import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
k = int(data[1])
p = int(data[2])
x = int(data[3])
y = int(data[4])
a = list(map(int, data[5:]))

result = find_marks(n, k, p, x, y, a)
print(" ".join(map(str, result)))
